import logging
from collections import OrderedDict
from random import randint

from taf.gnb.oam.ne3s.ws.components.UM.v1.resources.notifications.messages import UMNotificationGroup, \
    UMOperationNotification
from taf.gnb.oam.ne3s.ws.components.base import FunctionalComponent
from taf.gnb.oam.ne3s.ws.components.connection.ne3s_service import NE3SService
from taf.gnb.oam.ne3s.ws.components.UM.v1.resources.templates import templates

from taf.gnb.oam.ne3s.ws.components.exceptions import OperationFailed, OperationTimeout
from taf.gnb.oam.ne3s.ws.exceptions import StreamTimeoutError

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class UMv1(FunctionalComponent):
    STREAMS = None
    _connection = None
    SUPPORTED_NOTIFICATIONS = UMNotificationGroup
    USERACCOUNT = "USERACCOUNT"

    def __init__(self, connection):
        self._connection = connection
        self.STREAMS = []

    def set_local_account(self, adaptation_version, account_type, username, password, timeout):
        stream_name = "UM.set_local_account"
        dist_name = '{}/USERACCOUNT-{}'.format(adaptation_version, account_type)

        stream = self.add_new_msg_stream(stream_name=stream_name,
                                         msg_list=[UMOperationNotification])

        try:
            provision_content = templates.get_file_content('set_local_account.txt', 'r')

            provision_content = provision_content.format(
                dist_name=dist_name,
                mo_class=self.USERACCOUNT,
                username=username,
                password=password
            )

            log.info("Provision content: {}".format(provision_content))

            self.um_provision(provision_content=provision_content)

            notification = stream.get(timeout)

            if not self._is_set_local_account_successful(notification):
                raise OperationFailed(notification.attachment)
            else:
                return notification.attachment.status

        except StreamTimeoutError as e:
            err_msg = "Account setup confirmation was not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    @staticmethod
    def _is_set_local_account_successful(notification):
        is_um_operation_notification = isinstance(notification, UMOperationNotification)
        return is_um_operation_notification and notification.attachment.status == 'ok'

    def um_provision(self, provision_content):
        log.info("Starting provision")
        log.debug("Provision content: {}".format(provision_content))

        provision_action = 'provision'
        url = self._connection.create_soap_service_url(NE3SService.BULK)
        provision_soap = templates.get_file_content('um_provision.txt', 'r')

        cid_soap = '0.4596ec79-5043-4ef3-997f-5c0b092cceaf@example.jaxws.sun.com'
        cid_provision = '3596ec79-5043-4ef3-997f-5c0b092cceaf@example.jaxws.sun.com'

        random_number = randint(int(10e4), int(10e5))

        provision_soap = provision_soap.format(
            manager_registration_key=self._connection.REGISTRATION_KEY,
            session_id=self._connection.session_id,
            operation_id=random_number,
            provision_content='cid:{}'.format(cid_provision),
            manager_id=self._connection.connection_details.manager_id,
            plan_id=random_number
        )

        header_provision = {'Content-ID': '<{}>'.format(cid_provision)}
        header_soap = {'Content-ID': '<{}>'.format(cid_soap)}

        fields = OrderedDict()
        fields[cid_soap] = (cid_soap, provision_soap, 'text/xml', header_soap)
        fields[cid_provision] = (cid_provision, provision_content, 'text/xml',
                                 header_provision)

        provision_response = self._connection.send_multipart_soap_message(
            url, fields, action=provision_action)

        log.info("Provision message sent correctly and accepted")
        log.debug("Provision response content {}".format(provision_response))

        return provision_response
